    {
        $hex = '0123456789ABCDEF';
        $bytes = unpack('C*', $s);
        if ($bytes === false) {
            return '';
        }
        $out = '';
        foreach ($bytes as $b) {
            $isUnreserved =
                ($b >= 0x41 && $b <= 0x5A) ||
                ($b >= 0x61 && $b <= 0x7A) ||
                ($b >= 0x30 && $b <= 0x39) ||
                $b === 0x2D || $b === 0x2E || $b === 0x5F || $b === 0x7E;
            if ($isUnreserved) {
                $out .= chr($b);
            } else {
                $out .= '%' . $hex[$b >> 4] . $hex[$b & 0x0F];
            }
        }

        return $out;
    }
}
